package com.fream.back.domain.faq.service.kafka;

import com.fream.back.domain.faq.dto.PayAndAddressRequestDto;
import com.fream.back.domain.faq.dto.kafka.FaqProcessingEvent;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqStatus;
import com.fream.back.domain.faq.repository.FaqRepository;
import com.fream.back.domain.faq.service.command.FaqCommandService;
import com.fream.back.domain.notification.entity.Notification;
import com.fream.back.domain.notification.service.command.NotificationCommandService;
import com.fream.back.domain.address.entity.FaqAddress;
import com.fream.back.domain.address.service.command.FaqAddressCommandService;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import com.fream.back.domain.notice.entity.Notice;
import com.fream.back.domain.notice.service.command.NoticeCommandService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;





@Service
@RequiredArgsConstructor
@Slf4j
public class FaqEventConsumer {

    private final FaqRepository orderRepository;
    private final NotificationCommandService paymentCommandService;
    private final FaqAddressCommandService orderShipmentCommandService;
    private final NoticeCommandService warehouseStorageCommandService;
    private final ProductQueryService userQueryService;
    private final FaqEventProducer orderEventProducer;
    private final SimpMessagingTemplate messagingTemplate;
    private final KafkaTemplate<String, Map<String, Object>> notificationKafkaTemplate;





    @KafkaListener(
            topics = "order-processing-topic",
            groupId = "order-processing-group",
            containerFactory = "orderProcessingKafkaListenerContainerFactory"
    )
    @Transactional
    public void handleOrderProcessingEvent(
            @Payload FaqProcessingEvent event,
            Acknowledgment acknowledgment) {

        Instant start = Instant.now();

        try {
            log.info("주문 처리 이벤트 수신: 주문ID={}, 이벤트ID={}",
                    event.getOrderId(), event.getEventId());


            if (isOrderAlreadyProcessed(event.getOrderId())) {
                log.warn("이미 처리된 주문 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Faq order = orderRepository.findById(event.getOrderId())
                    .orElseThrow(() -> new IllegalArgumentException(
                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));

            Product user = userQueryService.findByEmail(event.getUserEmail());


            if (!order.getUser().getId().equals(user.getId())) {
                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
                        event.getOrderId(), order.getUser().getId(), user.getId());
                throw new IllegalArgumentException("주문과 사용자 정보가 일치하지 않습니다.");
            }


            processCompleteOrder(order, user, event.getRequestDto());


            sendSuccessNotification(event.getOrderId(), event.getUserEmail());


            acknowledgment.acknowledge();


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.info("주문 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());

        } catch (Exception e) {
            log.error("주문 처리 실패: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
            handleOrderProcessingFailure(event, e, acknowledgment);
        }
    }




    @KafkaListener(
            topics = "order-retry-topic",
            groupId = "order-retry-group",
            containerFactory = "orderProcessingKafkaListenerContainerFactory"
    )
    @Transactional
    public void handleOrderRetryEvent(
            @Payload FaqProcessingEvent event,
            Acknowledgment acknowledgment) {

        try {
            log.info("주문 재시도 처리: 주문ID={}, 재시도횟수={}",
                    event.getOrderId(), event.getRetryCount());

            if (event.isMaxRetryExceeded()) {
                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
                        event.getOrderId(), event.getRetryCount());


                sendFailureNotification(event.getOrderId(), event.getUserEmail(), "최대 재시도 횟수 초과");
                acknowledgment.acknowledge();
                return;
            }


            if (isOrderAlreadyProcessed(event.getOrderId())) {
                log.info("재시도 중 주문 완료 확인: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));


            handleOrderProcessingEvent(event, acknowledgment);

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            log.error("주문 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
            acknowledgment.acknowledge();
        } catch (Exception e) {
            log.error("주문 재시도 처리 중 오류: 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private void processCompleteOrder(Faq order, Product user, PayAndAddressRequestDto requestDto) {
        try {
            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());


            Notification payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
            order.assignPayment(payment);

            if (!payment.isSuccess()) {
                throw new RuntimeException("결제 실패: " + payment.getStatus());
            }

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());


            FaqAddress shipment = orderShipmentCommandService.createOrderShipment(
                    order,
                    requestDto.getReceiverName(),
                    requestDto.getReceiverPhone(),
                    requestDto.getPostalCode(),
                    requestDto.getAddress()
            );
            order.assignOrderShipment(shipment);
            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());


            if (!order.getStatus().canTransitionTo(FaqStatus.PAYMENT_COMPLETED)) {
                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
            }
            order.updateStatus(FaqStatus.PAYMENT_COMPLETED);

            if (requestDto.isWarehouseStorage()) {

                Notice warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
                order.assignWarehouseStorage(warehouseStorage);


                if (order.getStatus().canTransitionTo(FaqStatus.PREPARING)) {
                    order.updateStatus(FaqStatus.PREPARING);
                }
                if (order.getStatus().canTransitionTo(FaqStatus.IN_WAREHOUSE)) {
                    order.updateStatus(FaqStatus.IN_WAREHOUSE);
                }
                if (order.getStatus().canTransitionTo(FaqStatus.COMPLETED)) {
                    order.updateStatus(FaqStatus.COMPLETED);
                }

                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
            } else {

                if (order.getStatus().canTransitionTo(FaqStatus.PREPARING)) {
                    order.updateStatus(FaqStatus.PREPARING);
                }
                log.info("배송 준비 완료: 주문ID={}", order.getId());
            }


            orderRepository.save(order);
            log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());

        } catch (Exception e) {
            log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
            throw e;
        }
    }




    private boolean isOrderAlreadyProcessed(Long orderId) {
        try {
            Faq order = orderRepository.findById(orderId).orElse(null);
            if (order == null) {
                return false;
            }


            FaqStatus currentStatus = order.getStatus();
            return currentStatus != FaqStatus.PENDING_PAYMENT;

        } catch (Exception e) {
            log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
            return false;
        }
    }




    private void handleOrderProcessingFailure(FaqProcessingEvent event, Exception error, Acknowledgment acknowledgment) {
        try {

            if (isRetryableError(error)) {
                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
                orderEventProducer.sendOrderRetryEvent(event);
            } else {
                log.error("재시도 불가능한 오류로 주문 처리 실패: 주문ID={}, 오류={}",
                        event.getOrderId(), error.getMessage());
                sendFailureNotification(event.getOrderId(), event.getUserEmail(), error.getMessage());
            }

            acknowledgment.acknowledge();

        } catch (Exception e) {
            log.error("주문 처리 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private boolean isRetryableError(Exception error) {

        return !(error instanceof IllegalArgumentException) &&
                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
    }




    private void sendSuccessNotification(Long orderId, String userEmail) {
        try {
            Map<String, Object> notification = new HashMap<>();
            notification.put("orderId", orderId);
            notification.put("userEmail", userEmail);
            notification.put("status", "SUCCESS");
